// Text on an image, drawn as SVG outlines from the glyphs of assets/glyphs/ (Inter, generated by
// scripts/build-glyphs.ts). A caption measures and reads the same on every machine, and nothing waits
// on fontconfig, whose first scan of the system fonts took seconds.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { ENGINE } from '../core/config.ts';

interface Face {
  units: number;
  ascender: number;
  descender: number;
  glyphs: Record<string, [number, string]>;
  kern: Record<string, number>;
}

export type Weight = 400 | 600;
const faces = new Map<Weight, Face>();

function face(weight: Weight): Face {
  let f = faces.get(weight);
  if (!f) {
    f = JSON.parse(readFileSync(join(ENGINE, 'assets', 'glyphs', `inter-${weight}.json`), 'utf8')) as Face;
    faces.set(weight, f);
  }
  return f;
}

// A character the face does not have is drawn as « ? »: a caption stays as long as it was.
function glyph(f: Face, ch: string): [number, string] {
  return f.glyphs[ch] ?? f.glyphs['?'] ?? [f.units / 2, ''];
}

export function measure(text: string, size: number, weight: Weight = 400): number {
  const f = face(weight);
  let w = 0;
  let prev = '';
  for (const ch of text) {
    if (prev) w += f.kern[prev + ch] ?? 0;
    w += glyph(f, ch)[0];
    prev = ch;
  }
  return (w * size) / f.units;
}

export function ascent(size: number, weight: Weight = 400): number {
  const f = face(weight);
  return (f.ascender * size) / f.units;
}

// The text with its top-left corner at (x, y) — Pillow's default anchor — as one SVG group.
export function svgText(text: string, x: number, y: number, size: number, fill: string, weight: Weight = 400): string {
  const f = face(weight);
  const s = size / f.units;
  const baseline = y + ascent(size, weight);
  let pen = 0;
  let prev = '';
  const paths: string[] = [];
  for (const ch of text) {
    if (prev) pen += f.kern[prev + ch] ?? 0;
    const [adv, d] = glyph(f, ch);
    if (d) paths.push(`<path transform="translate(${pen} 0)" d="${d}"/>`);
    pen += adv;
    prev = ch;
  }
  return `<g fill="${fill}" transform="translate(${x} ${baseline}) scale(${s})">${paths.join('')}</g>`;
}

// Cut with « … » until it fits: the start of a file name says more than its end.
export function ellipsize(text: string, size: number, width: number, weight: Weight = 400): string {
  if (measure(text, size, weight) <= width) return text;
  let chars = Array.from(text);
  while (chars.length > 4 && measure(`${chars.join('')}…`, size, weight) > width) chars = chars.slice(0, -1);
  return `${chars.join('')}…`;
}

export function escapeXml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]!);
}

// A glyph's outline extent in font units, y down: its points' box (a font puts the extremes of a
// curve on the curve, so the control points do not widen it).
const extents = new Map<string, [number, number, number, number] | null>();
function extent(f: Face, weight: Weight, ch: string): [number, number, number, number] | null {
  const key = `${weight}:${ch}`;
  if (extents.has(key)) return extents.get(key)!;
  const nums = (glyph(f, ch)[1].match(/-?\d+(?:\.\d+)?/g) ?? []).map(Number);
  let box: [number, number, number, number] | null = null;
  for (let i = 0; i + 1 < nums.length; i += 2) {
    const x = nums[i]!;
    const y = nums[i + 1]!;
    if (!box) box = [x, y, x, y];
    else box = [Math.min(box[0], x), Math.min(box[1], y), Math.max(box[2], x), Math.max(box[3], y)];
  }
  extents.set(key, box);
  return box;
}

// What Pillow's textbbox((0, 0), text) gave: the ink box of the text drawn with its top-left corner
// at the origin, in whole pixels, its right edge reaching at least the advance.
export function inkBox(text: string, size: number, weight: Weight = 400): [number, number, number, number] {
  const f = face(weight);
  const s = size / f.units;
  const top = ascent(size, weight);
  let pen = 0;
  let prev = '';
  let box: [number, number, number, number] | null = null;
  for (const ch of text) {
    if (prev) pen += f.kern[prev + ch] ?? 0;
    const e = extent(f, weight, ch);
    if (e) {
      const g: [number, number, number, number] = [pen + e[0], e[1], pen + e[2], e[3]];
      box = box ? [Math.min(box[0], g[0]), Math.min(box[1], g[1]), Math.max(box[2], g[2]), Math.max(box[3], g[3])] : g;
    }
    pen += glyph(f, ch)[0];
    prev = ch;
  }
  if (!box) return [0, 0, Math.ceil(pen * s), 0];
  return [Math.floor(Math.min(0, box[0]) * s), Math.floor(top + box[1] * s), Math.ceil(Math.max(box[2], pen) * s), Math.ceil(top + box[3] * s)];
}
